#!/usr/bin/env python3
# constat:template id=pytest-check-report version=76 sha256=9007c788f6d7c24bc084d19ccac72166e3c8b95b7a9dc913c7af4a91918f22f2
# Generated by DoneMark's onboarding pull request. Turns pytest's own --junitxml report into the
# machine-readable per-check report CI publishes as the "constat-check-report" (and, on
# pull requests, "constat-check-report-base") workflow artifact. DoneMark's collector
# downloads that artifact and reads the named checks out of it — nothing an agent writes in its
# own report reaches this file.
#
# Usage: python3 .github/scripts/constat-pytest-report.py <junitXml> <outputFile> [--expected <headReport>]
#
# --expected is the before-code mode: every name the head report carried gets exactly one verdict,
# and a check that produced no result against the before-code (its file did not even import) is
# published as "could_not_run" rather than silently dropped. A load error is not a check biting.
#
# Nothing here imports anything outside Python's own standard library. pytest is what produced the
# XML; this script only has to read it, so a repository that can run its own tests can run this.

import json
import os
import re
import sys
import xml.etree.ElementTree as ET

SCHEMA = "constat.check-report/v1"
# A space, a greater-than sign, a space. The contract's separator, and the reason the name is built
# from its parts rather than taken from any single attribute: a space-joined name cannot be split
# back into the blocks it was made of.
SEPARATOR = " > "

USAGE = "usage: constat-pytest-report.py <junitXml> <outputFile> [--expected <headReport>]"


def die(message, code=1):
    print(message, file=sys.stderr)
    sys.exit(code)


def parse_arguments(argv):
    expected = None
    rest = list(argv)
    if "--expected" in rest:
        at = rest.index("--expected")
        if at + 1 >= len(rest):
            die(USAGE, 2)
        expected = rest[at + 1]
        rest = rest[:at] + rest[at + 2:]
    if len(rest) != 2:
        die(USAGE, 2)
    return rest[0], rest[1], expected


def slug(name):
    # The same rule as pictureSlug in @constat/shared, written out here because this file runs on a
    # bare runner with nothing of DoneMark's installed: lower-cased, every run of anything that is
    # not a letter or a digit becomes one dash, no leading or trailing dash, at most 120 characters.
    dashed = re.sub(r"[^a-z0-9]+", "-", name.lower())
    return dashed.strip("-")[:120]


def repo_relative(path):
    """The check's test file as the repository names it, never the runner's own disk path."""
    if not path:
        return None
    here = os.getcwd()
    if os.path.isabs(path):
        try:
            path = os.path.relpath(path, here)
        except ValueError:
            return path.replace(os.sep, "/")
    return path.replace(os.sep, "/")


def full_name(classname, title, file_path):
    """
    Every enclosing block, outermost first, then the check's own title, joined by the separator.

    pytest's JUnit XML gives the blocks as a dotted "classname" — the test's module, with its class
    appended where the test is in one — prefixed by the package path the module was collected
    under. The file attribute says where the module itself begins, so the package prefix is dropped
    rather than guessed at: "tests.test_tank.TankTest" against tests/test_tank.py is
    "test_tank > TankTest", which is the same shape as Elixir's "WaterMe.TankTest".
    """
    blocks = [part for part in (classname or "").split(".") if part]
    if file_path:
        module = os.path.basename(file_path)
        if module.endswith(".py"):
            module = module[:-3]
        if module in blocks:
            blocks = blocks[blocks.index(module):]
    return SEPARATOR.join(blocks + [title])


def first_line(words):
    """CI's own first line, for a check this report says failed. Never DoneMark's, and never a guess."""
    for line in (words or "").splitlines():
        if line.strip():
            return line.strip()
    return None


def checks_in(junit_path, with_pictures):
    pictures = os.path.join(os.getcwd(), ".constat", "pictures")
    checks = []
    for case in ET.parse(junit_path).getroot().iter("testcase"):
        title = case.get("name")
        if not title:
            continue
        file_path = repo_relative(case.get("file"))
        name = full_name(case.get("classname"), title, file_path)
        status = "passed"
        message = None
        # An <error> is pytest's word for a test whose setup or collection blew up. It is published
        # as "failed" and never as "could_not_run": the contract reserves that status to the
        # before-code report, where "the module was missing" must not read as "the check bit".
        broke = case.find("failure")
        if broke is None:
            broke = case.find("error")
        if broke is not None:
            status = "failed"
            message = first_line(broke.get("message") or broke.text)
        elif case.find("skipped") is not None:
            status = "skipped"
        check = {"name": name, "status": status, "file": file_path}
        if with_pictures:
            # The picture this check took, if it took one. The file's presence IS the message —
            # nothing has to tell this script the name.
            taken = slug(name) + ".png"
            if os.path.exists(os.path.join(pictures, taken)):
                check["picture"] = taken
        if message:
            check["message"] = message
        checks.append(check)
    return checks


def names_in(expected_path):
    with open(expected_path, "r", encoding="utf-8") as handle:
        body = json.load(handle)
    entries = body if isinstance(body, list) else body.get("checks", [])
    names = []
    for entry in entries:
        name = entry.get("name") if isinstance(entry, dict) else None
        if isinstance(name, str) and name and name not in names:
            names.append(name)
    return names


def main():
    junit_path, out_path, expected_path = parse_arguments(sys.argv[1:])
    if not os.path.exists(junit_path):
        die(junit_path + " does not exist — refusing to publish an empty check report. Did pytest run?")

    checks = checks_in(junit_path, with_pictures=expected_path is None)
    published = checks

    if expected_path is not None:
        if not os.path.exists(expected_path):
            die("expected head report " + expected_path + " does not exist — refusing to publish a "
                "before-code report with nothing to compare against.")
        names = names_in(expected_path)
        if not names:
            die("head report " + expected_path + " names no checks — nothing to compare against.")
        by_name = {}
        for check in checks:
            by_name.setdefault(check["name"], []).append(check)
        published = []
        for name in names:
            ran = by_name.get(name)
            published.extend(ran if ran else [{"name": name, "status": "could_not_run", "file": None}])

    where = os.path.dirname(os.path.abspath(out_path))
    if where:
        os.makedirs(where, exist_ok=True)
    with open(out_path, "w", encoding="utf-8") as handle:
        json.dump({"schema": SCHEMA, "checks": published}, handle, indent=2)
        handle.write("\n")
    print("wrote %d check(s) to %s%s" % (
        len(published), out_path,
        "" if expected_path is None else " (before-code mode, against " + expected_path + ")",
    ))


if __name__ == "__main__":
    main()
